import { useState, type ReactNode } from "react";

type PanelTab = { id: string; label: string; content: ReactNode };

export function IdeLayout({
  activityItems,
  sidebar,
  tabs,
}: {
  activityItems: string[];
  sidebar: ReactNode;
  tabs: PanelTab[];
}) {
  const [activeActivity, setActiveActivity] = useState(activityItems[0]);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState(tabs[0]?.id);
  const [panelOpen, setPanelOpen] = useState(true);

  const current = tabs.find((t) => t.id === activeTab) ?? tabs[0];

  return (
    <div className="ide-root" data-sidebar={sidebarOpen ? "open" : "closed"}>
      <nav className="ide-activity" aria-label="Activity">
        {activityItems.map((item) => (
          <button
            key={item}
            type="button"
            title={item}
            onClick={() => {
              setActiveActivity(item);
              setSidebarOpen(item === activeActivity ? !sidebarOpen : true);
            }}
            className={item === activeActivity ? "ide-activity-item is-active" : "ide-activity-item"}
          >
            {item.slice(0, 2)}
          </button>
        ))}
      </nav>

      {sidebarOpen ? <aside className="ide-sidebar">{sidebar}</aside> : null}

      <main className="ide-editor">
        <div className="ide-tabs" role="tablist">
          {tabs.map((t) => (
            <button
              key={t.id}
              type="button"
              role="tab"
              aria-selected={t.id === activeTab}
              onClick={() => setActiveTab(t.id)}
              className={t.id === activeTab ? "ide-tab is-active" : "ide-tab"}
            >
              {t.label}
            </button>
          ))}
        </div>
        <div className="ide-surface">{current?.content}</div>
      </main>

      <section className="ide-panel" data-open={panelOpen}>
        <button
          type="button"
          className="ide-panel-toggle"
          onClick={() => setPanelOpen((v) => !v)}
        >
          {panelOpen ? "▾ Output" : "▸ Output"}
        </button>
        {panelOpen ? <pre className="ide-output">ready — no errors</pre> : null}
      </section>
    </div>
  );
}

