.ide-root {
  display: grid;
  grid-template-columns: 48px 260px 1fr;
  grid-template-rows: 1fr auto;
  height: 100%;
  min-height: 460px;
  background: var(--surface-inset, #0b0d12);
  color: var(--text-strong, #d5dae6);
}
.ide-root[data-sidebar="closed"] {
  grid-template-columns: 48px 0 1fr;
}
.ide-activity {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 0;
  background: var(--surface-base, #0e1116);
  border-right: 1px solid var(--line-subtle, #1e2230);
}
.ide-activity-item {
  height: 36px;
  margin: 0 6px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted, #7c8598);
  font-size: 11px;
  cursor: pointer;
}
.ide-activity-item.is-active {
  background: var(--surface-raised, #171c26);
  color: var(--text-strong, #ffffff);
  box-shadow: inset 2px 0 0 var(--accent, #6366f1);
}
.ide-sidebar {
  overflow-y: auto;
  padding: 12px 10px;
  font-size: 12px;
  border-right: 1px solid var(--line-subtle, #1e2230);
}
.ide-editor {
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
}
.ide-tabs {
  display: flex;
  overflow-x: auto;
  background: var(--surface-base, #0e1116);
  border-bottom: 1px solid var(--line-subtle, #1e2230);
}
.ide-tab {
  padding: 8px 14px;
  font-size: 12px;
  white-space: nowrap;
  border: none;
  border-right: 1px solid var(--line-subtle, #1e2230);
  background: transparent;
  color: var(--text-muted, #7c8598);
  cursor: pointer;
}
.ide-tab.is-active {
  background: var(--surface-inset, #0b0d12);
  color: var(--text-strong, #ffffff);
  box-shadow: inset 0 2px 0 var(--accent, #6366f1);
}
.ide-surface {
  flex: 1;
  overflow: auto;
  padding: 20px;
}
.ide-panel {
  grid-column: 1 / -1;
  border-top: 1px solid var(--line-subtle, #1e2230);
  background: var(--surface-base, #0e1116);
}
.ide-panel-toggle {
  width: 100%;
  text-align: left;
  padding: 6px 12px;
  font-size: 11px;
  letter-spacing: 0.04em;
  border: none;
  background: transparent;
  color: var(--text-muted, #7c8598);
  cursor: pointer;
}
.ide-output {
  margin: 0;
  padding: 0 12px 12px;
  font-family: ui-monospace, monospace;
  font-size: 12px;
  line-height: 1.6;
  color: var(--text-muted, #93a0b8);
  max-height: 160px;
  overflow: auto;
}
